package dev.zeralius.clowder.execution.api;

import dev.zeralius.clowder.execution.domain.DriverEventType;
import dev.zeralius.clowder.execution.domain.FailureReason;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.Instant;

/**
 * @param idempotencyKey generated by the client, one per event, resent unchanged on every retry
 * @param planStopId which visit this is about; null for DEPARTED_DEPOT and RETURNED_DEPOT
 * @param occurredAt the device clock, which is used for ordering and nothing else
 */
public record RecordEventRequest(
        @NotBlank @Size(max = 64) String idempotencyKey,
        Long planStopId,
        @NotNull DriverEventType type,
        @NotNull Instant occurredAt,
        @DecimalMin("-90") @DecimalMax("90") BigDecimal latitude,
        @DecimalMin("-180") @DecimalMax("180") BigDecimal longitude,
        FailureReason failureReason) {}
